def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in store:
                _, wt = store[key]
                if t - wt >= ttl:
                    del store[key]
            if key in store:
                del store[key]
                store[key] = (value, t)
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    # evict LRU, but first check if any expired entries could be removed?
                    # Standard LRU eviction: evict least recently used regardless of expiry
                    store.popitem(last=False)
                store[key] = (value, t)
        else:
            _, t, key = op
            if key in store:
                value, wt = store[key]
                if t - wt >= ttl:
                    del store[key]
                    results.append(-1)
                else:
                    store.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)
    return results

